import { OrderRepository } from '../repositories/order-repository.js';

const orderRepository = new OrderRepository();

// Migrated to OrderRepository; callback signatures are kept for callers.
export function listOrdersForUser(userId, callback, repo = orderRepository) {
  repo.findByUser(userId).then(
    (orders) => callback(null, orders),
    (err) => callback(err),
  );
}

export function totalPaidCents(callback, repo = orderRepository) {
  repo.findPaid().then(
    (rows) => callback(null, rows.reduce((sum, o) => sum + o.total_cents, 0)),
    (err) => callback(err),
  );
}
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { findPaymentsForOrder, uncapturedTotalCents } from '../src/services/payment-service.js';

test('findPaymentsForOrder finds the payment for an order', (t, done) => {
  findPaymentsForOrder(10, (err, rows) => {
    assert.equal(err, null);
    assert.equal(rows.length, 1);
    assert.equal(rows[0].amount_cents, 4200);
    done();
  });
});

test('uncapturedTotalCents sums uncaptured payments', (t, done) => {
  uncapturedTotalCents((err, total) => {
    assert.equal(err, null);
    assert.equal(total, 9900);
    done();
  });
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { UserRepository } from '../src/repositories/user-repository.js';
import { OrderRepository } from '../src/repositories/order-repository.js';

test('UserRepository.findActive matches the service behaviour', async () => {
  const users = await new UserRepository().findActive();
  assert.equal(users.length, 2);
});

test('UserRepository.findByEmail returns the matching user or null', async () => {
  const repo = new UserRepository();
  const user = await repo.findByEmail('grace@example.com');
  assert.equal(user.id, 2);
  assert.equal(user.name, 'Grace');
  assert.equal(await repo.findByEmail('nobody@example.com'), null);
});

test('OrderRepository.findPaid matches the service behaviour', async () => {
  const orders = await new OrderRepository().findPaid();
  assert.equal(orders.length, 3);
});

test('OrderRepository.findQuotes returns only non-deleted quote orders', async () => {
  const orders = await new OrderRepository().findQuotes();
  assert.deepEqual(orders.map((o) => o.id), [11]);
  assert.ok(orders.every((o) => o.status === 'quote' && o.deleted_at === null));
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { listOrdersForUser, totalPaidCents } from '../src/services/order-service.js';

test('listOrdersForUser returns only that user orders', (t, done) => {
  listOrdersForUser(1, (err, orders) => {
    assert.equal(err, null);
    assert.equal(orders.length, 2);
    assert.ok(orders.every((o) => o.user_id === 1));
    done();
  });
});

test('listOrdersForUser reads through OrderRepository.findByUser', (t, done) => {
  const rows = [{ id: 7, user_id: 5 }];
  const repo = {
    findByUser: (userId) => {
      assert.equal(userId, 5);
      return Promise.resolve(rows);
    },
  };
  listOrdersForUser(5, (err, orders) => {
    assert.equal(err, null);
    assert.equal(orders, rows);
    done();
  }, repo);
});

test('listOrdersForUser passes repository errors to the callback', (t, done) => {
  const failure = new Error('boom');
  const repo = { findByUser: () => Promise.reject(failure) };
  listOrdersForUser(1, (err, orders) => {
    assert.equal(err, failure);
    assert.equal(orders, undefined);
    done();
  }, repo);
});

test('totalPaidCents counts only paid orders', (t, done) => {
  totalPaidCents((err, total) => {
    assert.equal(err, null);
    assert.equal(total, 4200 + 9900 + 500);
    done();
  });
});

test('totalPaidCents sums OrderRepository.findPaid results', (t, done) => {
  const repo = { findPaid: () => Promise.resolve([{ total_cents: 100 }, { total_cents: 250 }]) };
  totalPaidCents((err, total) => {
    assert.equal(err, null);
    assert.equal(total, 350);
    done();
  }, repo);
});

